examples.template:
MonarchDeviceList(
    devices,
    title: {{title}},
    description: {{description}},
    now: {{now|date}},
    onRemove: { id in
        // The app signs the device out on the server.
        try await Task.sleep(for: .milliseconds(300))
        devices.removeAll { $0.id == id }
    }
)

examples.code:
MonarchDeviceList(
    devices,
    title: "Devices",
    description: "Devices that have accessed your account.",
    now: Date(timeIntervalSince1970: 1_795_003_200),
    onRemove: { id in
        // The app signs the device out on the server.
        try await Task.sleep(for: .milliseconds(300))
        devices.removeAll { $0.id == id }
    }
)

VStack {
    MonarchDeviceList([], state: .loading)
    MonarchDeviceList([], state: .failed, onRetry: {})
}
